import { CanvasComponent } from '@blahblah/sdk';

export default class TitleCard extends CanvasComponent {
  static props = {
    title: { type: 'string', default: 'Welcome to BlahBlah' },
    subtitle: { type: 'string', default: 'Create video at the speed of thought' },
    color: { type: 'color', default: '#38bdf8' },
  };
  onUpdate({ time, props }) {
    const { ctx, canvasWidth, canvasHeight } = this;
    if (!ctx) return;
    ctx.clearRect(0, 0, canvasWidth, canvasHeight);
    ctx.fillStyle = props.color;
    ctx.font = 'bold 48px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(props.title, canvasWidth / 2, canvasHeight / 2 - 20);
    ctx.fillStyle = '#94a3b8';
    ctx.font = '24px sans-serif';
    ctx.fillText(props.subtitle, canvasWidth / 2, canvasHeight / 2 + 30);
  }
}

import { CanvasComponent } from '@blahblah/sdk';

export default class LowerThird extends CanvasComponent {
  static props = {
    name: { type: 'string', default: 'John Doe' },
    role: { type: 'string', default: 'Motion Designer' },
    accentColor: { type: 'color', default: '#6366f1' },
  };
  onUpdate({ time, props }) {
    const { ctx, canvasWidth, canvasHeight } = this;
    if (!ctx) return;
    const y = canvasHeight - 160;
    ctx.fillStyle = props.accentColor;
    ctx.fillRect(80, y, 6, 80);
    ctx.fillStyle = 'rgba(15, 23, 42, 0.85)';
    ctx.fillRect(86, y, 400, 80);
    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 28px sans-serif';
    ctx.fillText(props.name, 110, y + 36);
    ctx.fillStyle = '#94a3b8';
    ctx.font = '18px sans-serif';
    ctx.fillText(props.role, 110, y + 66);
  }
}

import { CanvasComponent } from '@blahblah/sdk';

export default class ProgressBar extends CanvasComponent {
  static props = {
    progress: { type: 'number', default: 60, min: 0, max: 100 },
    color: { type: 'color', default: '#38bdf8' },
    bgColor: { type: 'color', default: 'rgba(255,255,255,0.15)' },
    height: { type: 'number', default: 8, min: 2, max: 30 },
    margin: { type: 'number', default: 40, min: 0, max: 200 },
  };
  onUpdate({ time, props }) {
    const { ctx, canvasWidth, canvasHeight } = this;
    if (!ctx) return;
    const { progress = 60, color = '#38bdf8', bgColor = 'rgba(255,255,255,0.15)', height = 8, margin = 40 } = props;
    const y = canvasHeight - margin;
    const barWidth = canvasWidth - margin * 2;
    ctx.fillStyle = bgColor;
    ctx.beginPath();
    ctx.roundRect(margin, y, barWidth, height, 4);
    ctx.fill();
    const fillW = Math.max(0, Math.min(barWidth, (progress / 100) * barWidth));
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.roundRect(margin, y, fillW, height, 4);
    ctx.fill();
  }
}

import { CanvasComponent } from '@blahblah/sdk';

export default class CodeSnippet extends CanvasComponent {
  static props = {
    filename: { type: 'string', default: 'main.js' },
    code: { type: 'string', default: 'const greeting = "Hello World!";\nconsole.log(greeting);' },
    theme: { type: 'color', default: '#0f172a' },
  };
  onUpdate({ time, props }) {
    const { ctx, canvasWidth, canvasHeight } = this;
    if (!ctx) return;
    const { filename, code, theme } = props;
    const x = 60, y = 80, w = 600, h = 300, r = 10;
    ctx.fillStyle = theme;
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, r);
    ctx.fill();
    const dots = ['#ef4444', '#f59e0b', '#10b981'];
    dots.forEach((c, i) => {
      ctx.fillStyle = c;
      ctx.beginPath();
      ctx.arc(x + 20 + i * 16, y + 20, 5, 0, Math.PI * 2);
      ctx.fill();
    });
    ctx.fillStyle = '#64748b';
    ctx.font = '12px monospace';
    ctx.fillText(filename, x + 84, y + 24);
    ctx.fillStyle = '#38bdf8';
    ctx.font = '15px monospace';
    const lines = (code || '').split('\n');
    lines.forEach((l, i) => {
      ctx.fillText(l, x + 24, y + 68 + i * 26);
    });
  }
}
